package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import android.media.*;import java.io.*;
/** Explicit playback only. No audio focus or media-key commands. */
final class MeetingLocalPlayer {
 final Activity owner;final String id;final int parts;final TextView status;int generation;MediaPlayer player;File current;
 MeetingLocalPlayer(Activity a,String id,int parts,TextView s){owner=a;this.id=id;this.parts=parts;status=s;}
 void stop(){generation++;if(player!=null){try{player.release();}catch(Exception ignored){}player=null;}if(current!=null){current.delete();current=null;}status.setText("再生停止");}
 void play(long ms){stop();if(parts<1){status.setText("保存された音声区間がありません");return;}long safe=Math.max(0,Math.min(ms,parts*10000L-1));load((int)(safe/10000),(int)(safe%10000),generation);}
 void load(int part,int offset,int ticket){status.setText("音声を準備中（区間 "+(part+1)+"/"+parts+"）");new Thread(()->{File temp=null;try{byte[] wav=MeetingAudioStore.audio(MeetingAudioStore.folder(owner,id),part);temp=File.createTempFile("meeting-play-",".wav",owner.getCacheDir());try(FileOutputStream out=new FileOutputStream(temp)){out.write(wav);}final File prepared=temp;owner.runOnUiThread(()->{if(ticket!=generation||owner.isDestroyed()){prepared.delete();return;}try{if(player!=null)player.release();if(current!=null)current.delete();current=prepared;MediaPlayer next=new MediaPlayer();player=next;next.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build());next.setDataSource(prepared.getAbsolutePath());next.setOnPreparedListener(mp->{if(ticket!=generation){mp.release();return;}status.setText("会議音声を再生中（区間 "+(part+1)+"/"+parts+"）");if(offset>0){mp.setOnSeekCompleteListener(done->{if(ticket==generation)done.start();});mp.seekTo(Math.min(offset,Math.max(0,mp.getDuration()-1)));}else mp.start();});next.setOnCompletionListener(mp->{if(ticket!=generation)return;if(part+1<parts)load(part+1,0,ticket);else stop();});next.setOnErrorListener((mp,w,e)->{if(ticket==generation){stop();status.setText("この音声区間を再生できません。保存区間の検証をしてください");}return true;});next.prepareAsync();}catch(Exception e){prepared.delete();stop();status.setText("音声を再生できません");}});}catch(Exception e){if(temp!=null)temp.delete();owner.runOnUiThread(()->{if(ticket==generation)status.setText("保存音声を取得できません。元のグラス録音を保持してください");});}},"LocalMeetingPlay").start();}
}
